1241 | /* ===== Animações ===== */
1242 | 
1243 | @keyframes pulse-play {
1244 |   0%, 100% {
1245 |     box-shadow: 0 0 4px rgba(0, 255, 136, 0.2);
1246 |   }
1247 |   50% {
1248 |     box-shadow: 0 0 12px rgba(0, 255, 136, 0.5);
1249 |   }
1250 | }
1251 | 
1252 | .player-controls.playing .play-btn {
1253 |   animation: pulse-play 2s ease-in-out infinite;
1254 | }
1255 | 
1256 | .now-playing-info {
1257 |   transition: opacity 0.3s ease-in-out;
1258 | }
1259 | 
1260 | .track-title {
1261 |   transition: color 0.2s ease;
1262 | }
1263 | 
1264 | /* ===== Modo Compacto ===== */
1265 | 
1266 | .compact-toggle-btn {
1267 |   width: 24px;
1268 |   height: 22px;
1269 |   border: 1px solid var(--winamp-border);
1270 |   border-radius: 2px;
1271 |   background: var(--winamp-primary);
1272 |   color: var(--winamp-text);
1273 |   font-size: 12px;
1274 |   cursor: pointer;
1275 |   display: flex;
1276 |   align-items: center;
1277 |   justify-content: center;
1278 |   transition: background 0.15s;
1279 |   flex-shrink: 0;
1280 |   line-height: 1;
1281 | }
1282 | 
1283 | .compact-toggle-btn:hover {
1284 |   background: var(--winamp-secondary);
1285 |   border-color: var(--winamp-accent-dim);
1286 | }
1287 | 
1288 | .player-controls-compact {
1289 |   display: flex;
1290 |   align-items: center;
1291 |   gap: 8px;
1292 |   padding: 6px 12px;
1293 |   background: var(--winamp-primary);
1294 |   border: 1px solid var(--winamp-border);
1295 |   border-radius: var(--border-radius);
1296 | }
1297 | 
1298 | .player-controls-compact .now-playing-info {
1299 |   flex: 1;
1300 |   overflow: hidden;
1301 |   white-space: nowrap;
1302 |   text-overflow: ellipsis;
1303 | }
1304 | 
1305 | .player-controls-compact .track-title {
1306 |   font-size: 12px;
1307 |   color: var(--winamp-accent);
1308 | }
1309 | 
1310 | .player-controls-compact .ctrl-btn {
1311 |   width: 28px;
1312 |   height: 26px;
1313 |   border: 1px solid var(--winamp-border);
1314 |   border-radius: var(--border-radius);
1315 |   background: var(--winamp-primary);
1316 |   color: var(--winamp-text);
1317 |   font-size: 14px;
1318 |   cursor: pointer;
1319 |   display: flex;
1320 |   align-items: center;
1321 |   justify-content: center;
1322 |   transition: all 0.15s;
1323 |   flex-shrink: 0;
1324 | }
1325 | 
1326 | .player-controls-compact .ctrl-btn:hover {
1327 |   background: var(--winamp-secondary);
1328 |   border-color: var(--winamp-accent-dim);
1329 | }
1330 | 
1331 | .player-controls-compact .play-btn {
1332 |   width: 32px;
1333 |   height: 30px;
1334 |   font-size: 16px;
1335 |   background: var(--winamp-accent-dim);
1336 |   border-color: var(--winamp-accent);
1337 |   color: #fff;
1338 | }
1339 | 
1340 | .player-controls-compact .play-btn:hover {
1341 |   background: var(--winamp-accent);
1342 |   box-shadow: 0 0 8px rgba(0, 255, 136, 0.3);
1343 | }
1344 | 
1345 | /* ===== Ordenação da Playlist ===== */
1346 | 
1347 | .playlist-sort-bar {
1348 |   display: flex;
1349 |   gap: 4px;
1350 |   padding: 4px 8px;
1351 |   border-bottom: 1px solid var(--winamp-border);
1352 |   background: rgba(0, 0, 0, 0.08);
1353 | }
1354 | 
1355 | .playlist-sort-btn {
1356 |   flex: 1;
1357 |   padding: 3px 6px;
1358 |   font-family: var(--font-mono);
1359 |   font-size: 10px;
1360 |   border: 1px solid var(--winamp-border);
1361 |   border-radius: var(--border-radius);
1362 |   background: var(--winamp-primary);
1363 |   color: var(--winamp-text-dim);
1364 |   cursor: pointer;
1365 |   transition: all 0.15s;
1366 |   text-align: center;
1367 |   white-space: nowrap;
1368 | }
1369 | 
1370 | .playlist-sort-btn:hover {
1371 |   background: var(--winamp-secondary);
1372 |   color: var(--winamp-text);
1373 |   border-color: var(--winamp-accent-dim);
1374 | }
1375 | 
1376 | .playlist-sort-btn.active {
1377 |   color: var(--winamp-accent);
1378 |   border-color: var(--winamp-accent-dim);
1379 |   background: rgba(0, 255, 136, 0.08);
1380 | }
